// List of languages actually usable — every code here MUST have a full entry
// in TRANSLATIONS above (or it silently falls back to English keys/fallbacks).
export const NATIVE_NAMES = {
  en: "English", hi: "हिन्दी", bn: "বাংলা", ta: "தமிழ்",
  te: "తెలుగు", mr: "मराठी", gu: "ગુજરાતી", kn: "ಕನ್ನಡ",
  ml: "മലയാളം", pa: "ਪੰਜਾਬੀ",
};

// Convenience export for building <select> / dropdown language pickers
// consistently across every page instead of each page hardcoding its own list.
export const AVAILABLE_LANGUAGES = Object.keys(NATIVE_NAMES).map((code) => ({
  code,
  nativeName: NATIVE_NAMES[code],
}));

// ═══════════════════════════════════════════════════════════════════════════════
// PROVIDER
// ═══════════════════════════════════════════════════════════════════════════════
export function LanguageProvider({ children }) {
  const { getAuthHeaders, token } = useAuth();

  const [languageCode, setLanguageCode] = useState("en");
  const [nativeName, setNativeName] = useState("English");
  const [translations, setTranslations] = useState(TRANSLATIONS.en);
  const [loading, setLoading] = useState(false);

  // Keep a ref to the latest auth bits so the mount effect below can read
  // fresh values without re-running (and without needing an eslint-disable).
  const authRef = useRef({ token, getAuthHeaders });
  useEffect(() => {
    authRef.current = { token, getAuthHeaders };
  }, [token, getAuthHeaders]);

  const buildUrl = (path) => {
    const baseUrl = (API_BASE_URL || "http://localhost:8000").replace(/\/+$/, "");
    const cleanPath = path.replace(/^\/+/, "");
    return `${baseUrl}/${cleanPath}`;
  };

  // ─── CHANGE LANGUAGE (immediate, client-side first) ───
  const changeLanguage = useCallback(async (code) => {
    // 1. IMMEDIATELY switch UI to new language — always fall back to the
    // English dictionary so t() never has to return a raw key.
    setLanguageCode(code);
    setNativeName(NATIVE_NAMES[code] || code);
    setTranslations({ ...TRANSLATIONS.en, ...(TRANSLATIONS[code] || {}) });

    // 2. Save to localStorage
    try {
      localStorage.setItem("preferred_language", code);
    } catch (err) {
      // localStorage can throw in private-browsing / storage-restricted contexts
      console.warn("Could not persist language preference:", err);
    }

    // 3. Try to fetch extended translations from backend (optional, additive)
    const { token: currentToken, getAuthHeaders: currentGetAuthHeaders } = authRef.current;
    if (currentToken && code !== "en") {
      setLoading(true);
      try {
        // Save preference to backend
        await fetch(buildUrl("api/languages/user-preference"), {
          method: "PUT",
          headers: currentGetAuthHeaders(),
          body: JSON.stringify({ language_code: code }),
          signal: AbortSignal.timeout(3000),
        });
        // No error if this fails — backend might not exist yet

        // Try to load extended translations from backend
        const transRes = await fetch(buildUrl(`api/languages/${code}/translations`), {
          headers: currentGetAuthHeaders(),
          signal: AbortSignal.timeout(3000),
        });
        if (transRes.ok) {
          const data = await transRes.json();
          const map = {};
          (data.translations || []).forEach((t) => {
            map[t.key] = t.value;
          });
          // Merge on top of built-in (backend translations take priority),
          // always keeping English as the ultimate fallback layer.
          setTranslations((prev) => ({ ...prev, ...map }));
        }
      } catch (err) {
        // Backend not available — built-in translations still work
        console.log("Using built-in translations (backend unavailable)");
      } finally {
        setLoading(false);
      }
    }
  }, []); // stable identity — reads fresh auth via authRef, doesn't need to change

  // ─── LOAD SAVED LANGUAGE ON MOUNT ───
  useEffect(() => {
    let saved = null;
    try {
      saved = localStorage.getItem("preferred_language");
    } catch (err) {
      // ignore — localStorage unavailable
    }
    if (saved && saved !== "en" && TRANSLATIONS[saved]) {
      changeLanguage(saved);
    }
    // changeLanguage has a stable identity (empty dep array), so it's safe
    // to omit here without risking a stale closure.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ─── TRANSLATE HELPER ───
  // Memoized so its identity only changes when the active language's
  // dictionary actually changes — safe to use as a useEffect/useMemo dep
  // in consuming components.
  const t = useCallback(
    (key, fallback) => translations[key] || fallback || TRANSLATIONS.en[key] || key,
    [translations]
  );

  // Memoize the context value so LanguageProvider re-rendering for unrelated
  // reasons (e.g. AuthContext updates) doesn't force every single consumer
  // in the app to re-render.
  const value = useMemo(
    () => ({
      languageCode,
      nativeName,
      translations,
      loading,
      changeLanguage,
      t,
      availableLanguages: AVAILABLE_LANGUAGES,
    }),
    [languageCode, nativeName, translations, loading, changeLanguage, t]
  );

  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  );
}